import {AudioEngine} from './engine.js';
import {pulseEdges} from './keylock-metrics.js';
const sr=48000,freqs=[330,550,770,990],assert=(x,m)=>{if(!x)throw new Error(m);};
function tone(c,hz,duration=2){const b=c.createBuffer(1,Math.ceil(duration*sr),sr),data=b.getChannelData(0);for(let n=0;n<data.length;n++)data[n]=.1*Math.sin(2*Math.PI*hz*n/sr);return b;}
function amplitude(data,hz,from=.25,to=.65){let re=0,im=0,count=0;for(let n=Math.ceil(from*sr);n<Math.min(data.length,to*sr);n++){re+=data[n]*Math.cos(2*Math.PI*hz*n/sr);im+=data[n]*Math.sin(2*Math.PI*hz*n/sr);count++;}return 2*Math.hypot(re,im)/count;}
function setup(seconds=1,channels=2){const c=new OfflineAudioContext(channels,Math.ceil(seconds*sr),sr),e=new AudioEngine();e.buildGraph(c);return {c,e};}
function loadFour(e,c){assert(e.decks.length===4,'Four decks were not built');e.decks.forEach((d,i)=>{d.load(tone(c,freqs[i]));d.play(.05);});}
async function sideCheck(side){const {e,c}=setup();e.setCrossfade(side);loadFour(e,c);const out=await c.startRendering(),levels=freqs.map(f=>amplitude(out.getChannelData(0),f));levels.forEach((v,i)=>assert(i%2===side?v>.03:v<1e-5,`Wrong crossfader group: ${levels}`));return {crossfader:side,frequencies:freqs,amplitudes:levels};}
export const fourDeckChecks=[
  ['Four decks: LEFT endpoint contains A+C and excludes B+D',()=>sideCheck(0)],
  ['Four decks: RIGHT endpoint contains B+D and excludes A+C',()=>sideCheck(1)],
  ['THRU on C stays audible with crossfader right while A is excluded',async()=>{const {e,c}=setup();e.setDeckAssignment(2,'thru');e.setCrossfade(1);loadFour(e,c);const out=await c.startRendering(),levels=freqs.map(f=>amplitude(out.getChannelData(0),f));assert(levels[0]<1e-5&&levels.slice(1).every(v=>v>.03),JSON.stringify(levels));return {amplitudes:levels};}],
  ['PFL from C+D sums only in LEFT headphones despite muted channel/master levels',async()=>{const {e,c}=setup();e.setOutputMode('split');e.setMaster(0);e.setCrossfade(0);for(const i of [2,3]){const d=e.decks[i];d.load(tone(c,freqs[i]));d.level.gain.value=0;d.setCue(true);d.play(.05);}const out=await c.startRendering(),left=[2,3].map(i=>amplitude(out.getChannelData(0),freqs[i])),right=[2,3].map(i=>amplitude(out.getChannelData(1),freqs[i]));assert(left.every(v=>v>.04)&&right.every(v=>v<1e-7),JSON.stringify({left,right}));return {left,right};}],
  ['Four concurrent key-lock processors preserve four independent pitches at different tempos',async()=>{const {e,c}=setup(2),rates=[.84,1.16,.92,1.08];for(let i=0;i<4;i++){const d=e.decks[i];e.setDeckAssignment(i,'thru');d.load(tone(c,freqs[i],2.5));await d.setKeyLock(true);d.setRate(rates[i]);d.play(.15);}const out=await c.startRendering(),levels=freqs.map(f=>amplitude(out.getChannelData(0),f,.5,1.5));assert(levels.every(v=>v>.025),JSON.stringify(levels));return {rates,expectedPitchHz:freqs,originalPitchAmplitudes:levels};}],
  ['Chosen leader C aligns A+B+D on the real audio clock and rejects self-sync',async()=>{const {e,c}=setup(10,4),grids=[{bpm:120,gridAnchor:.113},{bpm:124,gridAnchor:.217},{bpm:128,gridAnchor:.173},{bpm:126,gridAnchor:.319}];for(const gate of [e.stereoGate,e.splitGate]){gate.gain.cancelScheduledValues(0);gate.gain.value=0;}
    grids.forEach((g,i)=>{const b=c.createBuffer(1,16*sr,sr),data=b.getChannelData(0);for(let t=g.gridAnchor;t<16;t+=60/g.bpm)for(let n=0;n<96;n++){const at=Math.round(t*sr)+n;if(at<data.length)data[at]=.5;}e.decks[i].load(b);e.decks[i].seek(i===2?1.37:4.15);});
    e.decks[2].play();const plans=[0,1,3].map(i=>e.syncTo(i,grids[i],grids[2],2));let rejected=false;try{e.syncTo(2,grids[2],grids[2],2);}catch{rejected=true;}assert(rejected,'Self-sync accepted');
    const probe=c.createChannelMerger(4);e.decks.forEach((d,i)=>d.sourceGain.connect(probe,0,i));probe.connect(c.destination);const out=await c.startRendering(),edges=e.decks.map((_,i)=>pulseEdges(out.getChannelData(i),sr).times),leader=edges[2];assert(leader.length>=19,'Too few beats');const maxError=edges.map(list=>{assert(list.length===leader.length,'Missing beats');return Math.max(...list.map((p,i)=>Math.abs(p-leader[i])))/sr*1000;});assert(maxError.every(n=>n<=1000/sr+.001),JSON.stringify(maxError));return {leader:'C',matchedBeats:leader.length,rates:plans.map(p=>p.rate),maxErrorMilliseconds:maxError};
  }],
  ['Live master recording contains all four decks and excludes headphone-only sampler',async()=>{const e=new AudioEngine(),c=new AudioContext({sampleRate:sr});e.buildGraph(c);for(const g of [e.stereoGate,e.splitGate]){g.gain.cancelScheduledValues(0);g.gain.value=0;}try{await c.resume();const codec=['audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));assert(codec,'No recording codec');const chunks=[],r=new MediaRecorder(e.recordBus.stream,{mimeType:codec}),stopped=new Promise((resolve,reject)=>{r.ondataavailable=ev=>chunks.push(ev.data);r.onstop=resolve;r.onerror=()=>reject(new Error('Recorder failed'));});e.decks.forEach((d,i)=>d.load(tone(c,freqs[i])));e.sampler.assign(0,tone(c,1320),{start:0,duration:1});e.sampler.setRoute('headphones');r.start();e.decks.forEach(d=>d.play());e.sampler.trigger(0);await new Promise(resolve=>setTimeout(resolve,1000));r.stop();await stopped;const blob=new Blob(chunks,{type:codec}),out=await c.decodeAudioData(await blob.arrayBuffer()),data=out.getChannelData(0),levels=freqs.map(f=>amplitude(data,f)),cue=amplitude(data,1320);assert(levels.every(v=>v>.02)&&cue<.001,JSON.stringify({levels,cue}));return {codec,bytes:blob.size,duration:out.duration,fourDeckAmplitudes:levels,headphoneSamplerLeak:cue};}finally{e.decks.forEach(d=>d.pause());e.sampler.stopAll();await c.close();}}]
];

